// CombatLogKind is what a combat log entry tells.
type CombatLogKind int32

const (
	CombatLogKind_COMBAT_LOG_KIND_UNSPECIFIED CombatLogKind = 0
	// The combat began (round 1).
	CombatLogKind_COMBAT_LOG_KIND_COMBAT_BEGUN CombatLogKind = 1
	// An attack: the attacker, the target, the roll, the outcome and, once
	// rolled, the damage (`damage`). One entry for the whole attack: the
	// damage lands in the entry of the attack that caused it.
	CombatLogKind_COMBAT_LOG_KIND_ATTACK CombatLogKind = 2
	// A standard action: the actor and `key`.
	CombatLogKind_COMBAT_LOG_KIND_ACTION CombatLogKind = 3
	// A combatant moved on its turn: the actor and `distance_ft`.
	CombatLogKind_COMBAT_LOG_KIND_MOVED CombatLogKind = 4
	// The master changed an NPC's hit points by hand. Master only.
	CombatLogKind_COMBAT_LOG_KIND_HIT_POINTS_ADJUSTED CombatLogKind = 5
	// The master hid or revealed a combatant (`now_hidden`). Master only.
	CombatLogKind_COMBAT_LOG_KIND_REVEAL_CHANGED CombatLogKind = 6
	// The combat ended.
	CombatLogKind_COMBAT_LOG_KIND_COMBAT_ENDED CombatLogKind = 7
	// A spell was cast: the caster, the slot and, in `spell`, what it did to each
	// target (the roll, the save, the damage once rolled).
	CombatLogKind_COMBAT_LOG_KIND_SPELL_CAST CombatLogKind = 8
	// A reaction was used: the actor and the spell (`key`, `spell`). When it
	// stopped an attack, that attack's entry says so (stopped_by_reaction).
	CombatLogKind_COMBAT_LOG_KIND_REACTION CombatLogKind = 9
	// A death save: the actor and `death_save`.
	CombatLogKind_COMBAT_LOG_KIND_DEATH_SAVE CombatLogKind = 10
	// The master confirmed a character's death: the target.
	CombatLogKind_COMBAT_LOG_KIND_DEATH_CONFIRMED CombatLogKind = 11
	// The conditions or the concentration of a combatant changed: the target,
	// `conditions` and `concentration_ended_key`.
	CombatLogKind_COMBAT_LOG_KIND_CONDITIONS_CHANGED CombatLogKind = 12
	// A member of a joint turn ended their part and the turn goes on ("Brisa
	// encerrou a parte dela"): the actor. The last part to end is not a line:
	// the turn passes. A line with a hidden member never reaches a player.
	CombatLogKind_COMBAT_LOG_KIND_TURN_PART_ENDED CombatLogKind = 13
	// A trap fired (MR-035): the trap's name (it is public now) and `trap`, with what
	// happened to each creature it caught. A fired trap is never a secret of
	// the master's, so every player gets the line; the dice of the other creatures
	// and every DC stay with the master (RN-10, RN-20).
	CombatLogKind_COMBAT_LOG_KIND_TRAP_TRIGGERED CombatLogKind = 20
	// A druid took a beast form or left it (MR-037): the actor and `wild_shape`.
	// Everyone who sees the actor gets the line; the damage the beast's fall carried
	// over to the druid is the druid's player's and the master's alone (RN-20).
	CombatLogKind_COMBAT_LOG_KIND_WILD_SHAPE CombatLogKind = 21
	// A move opened a closed door (RN-26, "Toren abriu a porta"): the actor and
	// `door`. On a map without the fog everyone gets the line; with the fog, the players whose character saw or remembers the door when it opened, and the mover's player (RN-10). Any combatant's move can open a door. The
	// master's undo of the move does not close the door, so the line stays.
	CombatLogKind_COMBAT_LOG_KIND_DOOR_OPENED CombatLogKind = 22
	// The master offered an opportunity attack in a combat without a map (RN-25,
	// OfferOpportunity): "Goblin 1 saiu do alcance de Toren", the mover as the actor
	// and the reactor as the target. Only the master, the reactor's player and the
	// mover's player get the line, as they get the offer (RN-10: a hidden combatant
	// in it keeps it from every player). The offer's answer (declined, skipped,
	// withdrawn) belongs to this line, so the master can undo it from here
	// (`undoable`); the attack of an answer is its own ATTACK line.
	CombatLogKind_COMBAT_LOG_KIND_OPPORTUNITY_OFFERED CombatLogKind = 23
	// The master put monsters in the combat (AddMonsters, RN-29): `monsters`, with
	// the hit points of each and the dice when they were rolled ("Bandido 1: 9 PV
	// (2d8 + 2: 3, 4)"). Only the master gets the line, and it also comes from
	// before the combat begins (round 0).
	CombatLogKind_COMBAT_LOG_KIND_MONSTERS_ADDED CombatLogKind = 24
	// A zone was put, moved, ended, dispersed, or caught a creature (W7-Z): `zone`. A
	// creature is named only to whoever saw it when it happened; the caster, the DC and
	// the dice of an NPC's zone are never a player's (RN-10, RN-20).
	CombatLogKind_COMBAT_LOG_KIND_ZONE CombatLogKind = 25
)

